var SolaimanLipi = '';
var Kalpurush = '';
var NotoSerifBengali = '';
var Bangla = '';
var Suttony = '';

//export default font;

import { jsPDF } from "jspdf"
var callAddFont = function () {
this.addFileToVFS('SolaimanLipi.ttf', SolaimanLipi);
this.addFont('SolaimanLipi.ttf', 'SolaimanLipi', 'normal');

this.addFileToVFS('Kalpurush.ttf', Kalpurush);
this.addFont('Kalpurush.ttf', 'Kalpurush', 'normal');

this.addFileToVFS('NotoSerifBengali.ttf', Kalpurush);
this.addFont('NotoSerifBengali.ttf', 'NotoSerifBengali', 'normal');

this.addFileToVFS('Bangla.ttf', Bangla);
this.addFont('Bangla.ttf', 'Bangla', 'normal');

this.addFileToVFS('Suttony.ttf', Suttony);
this.addFont('Suttony.ttf', 'Suttony', 'normal');
};
jsPDF.API.events.push(['addFonts', callAddFont])

